import type { Prisma } from '@prisma/client';
import { imageKeySchema, newImageKey } from '../../lib/image-keys.js';
import { getImageProcessor, getImageStorage } from './image.ports.js';
import { findCopyRoot, insertImageCopy } from './image.repository.js';

/**
 * Copies a product photo to a new file under a new random key, re-encoded with a small
 * invisible variation (`vary: true`), so two shops copying one photo share no file and
 * cannot be linked by their files (C-56). The new key is generated by the server and never
 * derived from the source (ASVS v5.0.0-5.3.2).
 *
 * The registry row `(copy, source, root)` is inserted in the caller's transaction; `root` is
 * the root of the source when the source is itself a copy, else the source. Storage is not
 * transactional: if the caller's transaction fails, the new file stays until the nightly
 * cleanup (IMG-007). The registry is never returned to any client.
 * @returns the new key, or null when the source file is gone (the caller keeps the card
 * without that photo).
 * @throws {RangeError} when the key is not a canonical `products/` key (a logo or a profile
 * photo is never copied).
 */
export async function copyImage(
  tx: Prisma.TransactionClient,
  sourceKey: string
): Promise<string | null> {
  if (!imageKeySchema.safeParse(sourceKey).success || !sourceKey.startsWith('products/')) {
    throw new RangeError('Only a product photo can be copied');
  }

  const storage = getImageStorage();
  const source = await storage.get(sourceKey);
  if (source === null) return null;

  const varied = await getImageProcessor().reencode(source, { vary: true });
  const copyKey = newImageKey('products');
  await storage.put(copyKey, varied);

  const rootKey = (await findCopyRoot(tx, sourceKey)) ?? sourceKey;
  await insertImageCopy(tx, { copyKey, sourceKey, rootKey });
  return copyKey;
}
